import styled from '@emotion/styled';
import { Paragraph } from 'components/UI';
import { theme } from 'theme';

export const StyledInsightsWrapper = styled.div({
  position: 'relative',
  width: '100%',
  display: 'flex',
  alignItems: 'stretch',
  minHeight: 0,
  padding: '0 32px',
  height: '100%',
});

interface StyledInsightsContainerProps {
  $titleRight?: boolean;
}

export const StyledInsightsContainer = styled.div<StyledInsightsContainerProps>(
  ({ $titleRight }) => ({
    display: 'flex',
    alignItems: 'stretch',
    width: '100%',
    borderRadius: '16px',
    overflow: 'hidden',
    border: '1px solid #14141429',
    backgroundColor: '#FFFFFF',
    position: 'relative',
    height: '100%',
    zIndex: 1,

    ...($titleRight === true && {
      flexDirection: 'row-reverse',
    }),
  }),
);

export const StyledTitleInsight = styled.div({
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  textAlign: 'center',
  padding: '24px 16px',
  backgroundColor: '#FAFAFA',
  minWidth: '280px',
  height: 'auto',
  fontFamily: theme.fonts.heading,
  color: '#141414',
});

export const StyledContentInsight = styled.div({
  flex: 1,
  padding: '54px 32px',
  color: '#141414',
  fontSize: '18px !important',
  lineHeight: '140% !important ',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'center',
  height: '100%',
  minHeight: 0,
  fontFamily: `${theme.fonts.paragraph} !important`,
  borderLeft: '1px solid #14141429',

  ul: {
    margin: 0,
    paddingLeft: '20px',
  },

  li: {
    marginBottom: '8px',
  },
});

export const StyledIndexBadge = styled.div({
  position: 'absolute',
  left: '8px',
  top: '50%',
  transform: 'translateY(-50%)',
  width: '48px',
  height: '48px',
  borderRadius: '100%',
  backgroundColor: '#F2F2F2',
  border: '1px solid rgba(20, 20, 20, 0.12)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  color: '#000000',
  zIndex: 2,
});

export const StyledContentWrapper = styled.div({
  fontSize: '18px !important',
  fontFamily: theme.fonts.paragraph,
});

export const StyledParagraph = styled(Paragraph)({
  fontSize: '18px !important',
  lineHeight: '20px !important',
});

export const StyledTitle = styled(Paragraph)({
  fontSize: '24px !important',
  lineHeight: '20px !important',
  fontWeight: '600 !important',
});
